import type { BereanApi } from '../api/types'
import type { GuestSnapshot } from '../api/memory'
import type { CreateNoteInput, CreatePassageInput } from '../types'

// Carrying a guest's notes into a freshly signed-in account (Root.tsx's
// enter()). The guest store is the memory api's plain rows; this turns them
// into the CreatePassageInput / CreateNoteInput calls the real api accepts, in
// an order that reproduces the guest's journal. Ids are regenerated by the
// api (they are per-workspace); what is preserved is every field the input
// types accept, including word-level highlights.
//
// `planGuestReplay` is pure so the mapping is testable without an api;
// `replayGuestSnapshot` executes a plan against one.

export interface ReplayPassage {
  passage: CreatePassageInput
  // In created_at order, so a sub-note (indent_level > 0) lands after the
  // note it hangs under, exactly as the guest wrote them.
  notes: Omit<CreateNoteInput, 'session_id'>[]
}

export interface ReplayPlan {
  passages: ReplayPassage[]
  categories: GuestSnapshot['categories']
  noteCount: number
}

export function planGuestReplay(snap: GuestSnapshot): ReplayPlan {
  const passageBySession = new Map<string, string>()
  for (const s of snap.sessions) passageBySession.set(s.id, s.passage_id)

  const notesByPassage = new Map<string, GuestSnapshot['notes']>()
  for (const n of snap.notes) {
    const passageId = passageBySession.get(n.session_id)
    // A note whose session or passage is missing has nothing to anchor to;
    // the memory api's cascade never leaves one, so this is only defensive.
    if (!passageId) continue
    const list = notesByPassage.get(passageId) ?? []
    list.push(n)
    notesByPassage.set(passageId, list)
  }

  const passages: ReplayPassage[] = []
  let noteCount = 0
  const ordered = [...snap.passages].sort((a, b) => a.created_at.localeCompare(b.created_at))
  for (const p of ordered) {
    const notes = notesByPassage.get(p.id)
    // An empty passage is storage plumbing, not something the guest made.
    if (!notes || notes.length === 0) continue
    notes.sort((a, b) => a.created_at.localeCompare(b.created_at))
    passages.push({
      passage: {
        book_number: p.book_number,
        chapter_start: p.chapter_start,
        verse_start: p.verse_start,
        chapter_end: p.chapter_end,
        verse_end: p.verse_end,
        reference_label: p.reference_label
      },
      notes: notes.map(n => ({
        content: n.content,
        anchor_start_verse: n.anchor_start_verse,
        anchor_end_verse: n.anchor_end_verse,
        anchor_book_override: n.anchor_book_override,
        anchor_chapter_override: n.anchor_chapter_override,
        category: n.category,
        indent_level: n.indent_level,
        highlighted_text: n.highlighted_text ?? null
      }))
    })
    noteCount += notes.length
  }

  return { passages, categories: snap.categories, noteCount }
}

/** Whether a snapshot has anything worth carrying over. */
export function guestSnapshotHasNotes(snap: GuestSnapshot | null): boolean {
  return snap !== null && planGuestReplay(snap).noteCount > 0
}

/**
 * Execute a plan against the real api: one passage, one session, then its
 * notes in order. Categories are carried only into an account that has not
 * customised its own — overwriting a returning reader's palette with a
 * guest's would be a loss, not a merge.
 */
export async function replayGuestSnapshot(api: BereanApi, snap: GuestSnapshot): Promise<number> {
  const plan = planGuestReplay(snap)
  if (plan.noteCount === 0) return 0
  let created = 0
  for (const entry of plan.passages) {
    const passage = await api.createPassage(entry.passage)
    const session = await api.createSession(passage.id)
    for (const note of entry.notes) {
      await api.createNote({ ...note, session_id: session.id })
      created++
    }
  }
  if (plan.categories.length > 0) {
    const existing = await api.getNoteCategories()
    if (existing.length === 0) await api.saveNoteCategories(plan.categories)
  }
  return created
}
